skinparam rectangleBorderColor #b0c2d3
skinparam activityBorderColor #006a62
skinparam activityBackgroundColor #e9f3f4
skinparam partitionBorderColor #b0c2d3
skinparam stereotypeCBackgroundColor #ffffff
title Feature and Integration CI
start
fork
  partition "Consolidated portable integra…" {
    :Checkout;
    :Validate localization JSON syntax;
    :Validate Artemis English/French translation…;
    :Validate release/CD contract;
    :Validate isolated VPN build contract;
    :Configure unit suite;
    :Build unit suite;
    :Run unit suite;
  }
fork again
  partition "Release source package contra…" {
    :Checkout repository and submodules;
    :Build dry-run source packages;
    :Inspect source packages;
  }
fork again
  partition "ASan + UBSan integration" {
    :Checkout;
    :Configure;
    :Build;
    :Test;
  }
fork again
  partition "Artemis CI summary" {
    :Require all integration jobs;
  }
end fork
stop
@enduml
